use vstd::prelude::*;

verus! {
    // Spec function to lowercase an ASCII character.
    spec fn lowercase(c: char) -> char {
        if 'A' <= c && c <= 'Z' {
            // ASCII 'A'..'Z' maps to 'a'..'z' by adding 32
            chr((c as u32) + 32)
        } else {
            c
        }
    }

    // Specification of ASCII‐case‐insensitive palindrome over a sequence of chars.
    spec fn is_pal_spec(s: Seq<char>) -> bool {
        // For every index i, the lowercase of s[i] equals the lowercase of its mirror.
        forall |i: nat|
            i < s.len() ==>
            lowercase(s[i]) == lowercase(s[s.len() - 1 - i])
    }

    // Implementation over a Vec<char>.
    fn is_palindrome(text: Vec<char>) -> (result: bool)
        ensures
            // The result agrees with the spec on the sequence view of text.
            result == is_pal_spec(text@)
    {
        // View the Vec as a Seq to use in specifications.
        let seq: Seq<char> = text@;
        let n: nat = seq.len();

        // Trivially true for lengths 0 or 1.
        if n < 2 {
            return true;
        }

        // We'll index into the Vec by usize; check it matches n.
        let len_usize: usize = text.len();
        assert(len_usize == n);

        // Compare characters up to the middle.
        let mut i: nat = 0;
        while i < n / 2
            invariant
                i <= n / 2,
                // All checked positions so far satisfy the palindrome property.
                forall |k: nat|
                    k < i ==>
                    lowercase(seq[k]) == lowercase(seq[n - 1 - k]),
            decreases (n / 2) - i
        {
            let c1: char = text[i as usize];
            let c2: char = text[len_usize - i as usize - 1];
            let l1 = lowercase(c1);
            let l2 = lowercase(c2);
            if l1 != l2 {
                return false;
            }
            i += 1;
        }

        // If we never found a mismatch, it's a palindrome.
        true
    }
}

fn main() {
    // Some quick sanity checks (not verified by Verus).
    assert(is_palindrome(vec![]));
    assert(is_palindrome(vec!['A']));
    assert(is_palindrome(vec!['A','b','A']));
    assert(is_palindrome(vec!['x','Y','y','X']));
    assert(!is_palindrome(vec!['a','B','c']));
}